 in the limericks. Each limerick should have a different rhyme scheme and should not repeat any words from previous limericks.

<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Bill Limericks</title>
</head>
<body>
    <h1>Bill Limericks</h1>
    <ul id="limericks"></ul>

    <script>
        // Get the list of limericks
        const limericks = document.getElementById('limericks');
        const keyword = 'bill';

        // Loop through each limerick
        for (let i = 0; i < 25; i++) {
            // Create the limerick
            const limerick = `
                ${i === 0 ? '' : '<br>'}
                A ${keyword} named Bill once said,
                He was a great economist, but he wasn't.
                His knowledge was vast, his wisdom was deep,
                And he could solve any problem with ease.
                But when it came to money, he couldn’t see the light,
                So he decided to change his name, and now he’s gone.
            `;

            // Add the limerick to the list
            limericks.appendChild(limerick);
        }
    </script>
</body>
</html>

